'use client';

import * as React from 'react';

// @interlace/account-menu v1.0.0 — Interlace design system.
// Docs, props and live preview: https://ds.interlace.tools/c/account-menu
// What changed since: https://ds.interlace.tools/c/account-menu#history
// Generated banner — keep it, the upgrade diff reads this version.

/**
 * @interlace/ui — AccountMenu
 *
 * The account control at the right end of a `Topbar`'s `actions` slot, for any sign-in service.
 * It has the three states every app with accounts has:
 *
 * 1. **Unknown.** The browser has not read the session yet. The control keeps exactly the room
 *    the answer will take, shows nothing, says nothing and cannot be focused.
 * 2. **Signed out.** A "Sign in" link that carries the page the person is on (`?next=`), and
 *    does not when they are already on the sign-in page.
 * 3. **Signed in.** Their photo, or their initials when there is none, as a menu button named
 *    "Account menu for Dana". The menu opens on a header (name and email), then the app's links,
 *    then "Sign out", which may take a moment and may fail.
 *
 * The component is a function of its props: it takes `state`. `useAccount(adapter)` builds that
 * state from the app's own service (Supabase, Auth.js, Clerk, a cookie), and the kit never reads
 * or writes a session. The pure helpers beside it (`accountDisplayName`, `accountInitials`,
 * `signInHref`, `safeReturnPath`) are in `account-menu-model`.
 *
 * ## The bar does not move
 *
 * The root keeps a minimum inline size, `--account-menu-room`, the width of the Sign in button at
 * its default label, and aligns its content to the end. So the neighbour to its left sits in the
 * same place in all three states, and the avatar (narrower) lands where Sign in's right edge was.
 * An app with a longer label sets the property. There is no fade between the states: a control
 * in the first viewport that fades in is a layout and paint cost for nothing.
 *
 * ## Flow
 *
 * A flow (docs/philosophies/FLOW_PHILOSOPHY.md) with one part: the app drives every phase through
 * `state` (usually from `useAccount`), so there is nothing to compose.
 *
 * | Phase       | Part                                         | Leaves by                                        |
 * | ----------- | -------------------------------------------- | ------------------------------------------------ |
 * | unknown     | AccountMenu, an inert placeholder            | the adapter answers → signed-out or signed-in    |
 * | signed-out  | AccountMenu, the Sign in link                | the person signs in (the app's page) → signed-in |
 * | signed-in   | AccountMenu, the avatar and its menu         | Sign out → signing-out                           |
 * | signing-out | AccountMenu, Sign out disabled, "Signing out…" | the promise settles → signed-out, or failed   |
 * | failed      | AccountMenu, a polite live region, `onError` | the person tries again → signing-out             |
 *
 * ## Anatomy
 *
 *   AccountMenu                    (div — data-slot="account-menu", data-state, min inline size = --account-menu-room)
 *     ├─ span                      (unknown: data-slot="account-menu-placeholder", aria-hidden, inert, invisible)
 *     ├─ a                         (signed-out: data-slot="account-menu-sign-in", buttonVariants outline sm)
 *     └─ DropdownMenu              (signed-in)
 *         ├─ Trigger               (data-slot="account-menu-trigger", aria-label = labels.menu(name), round)
 *         │   └─ Avatar            (image alt="", no-referrer, or initials aria-hidden)
 *         ├─ Content               (align end)
 *         │   ├─ Label             (name and email: a heading, not an item)
 *         │   ├─ Separator
 *         │   ├─ Item × links      (data-slot="account-menu-link", through `renderLink`)
 *         │   └─ Item              (data-slot="account-menu-sign-out")
 *         └─ span role=status      (data-slot="account-menu-live", visually hidden, polite)
 *
 * ## States
 *
 * Unknown, signed out, signed in (closed, open), image failed (initials show), no name and no
 * email (the fallback name, `?`), signing out, sign-out failed, long name or email (truncated,
 * full text in `title`), 320 px, RTL. Without JavaScript the server renders the unknown
 * placeholder: the session is read in the browser. A page that wants a Sign in link without
 * JavaScript renders its own `<noscript>` link beside this.
 *
 * ## Source of the API
 *
 * The slot and the three states are what apps with accounts write at the end of a header; the
 * adapter's `{ read, subscribe }` is the smallest shape that both a `getSession` plus
 * `onAuthStateChange` pair and an Auth.js `getSession` plus session event fit. It diverges from
 * those libraries on purpose: it names none of them.
 *
 * | Rule | Concept                  | Where                                                      |
 * | ---- | ------------------------ | ---------------------------------------------------------- |
 * | R6   | data-slot per part       | every part above                                           |
 * | R14  | declares a min viewport  | `MIN_VIEWPORT` on the root (`data-min-viewport`)           |
 * | R19  | tokens only              | `text-muted-foreground`, `ring-ring`, `size-control`       |
 * | R25  | client component         | the menu primitive and the live region need the browser    |
 * | R26  | A11y                     | named trigger, header is not an item, polite live region   |
 */

import { cn } from '@/lib/utils';
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar';
import { buttonVariants } from '@/components/ui/button-variants';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { VisuallyHidden } from '@/components/ui/visually-hidden';
import {
  accountDisplayName,
  accountInitials,
  DEFAULT_FALLBACK_NAME,
  signInHref as buildSignInHref,
  type Account,
  type AccountState,
} from '@/components/ui/patterns/account-menu-model';

export { useAccount, type AccountAdapter } from '@/components/ui/patterns/use-account';
export type { Account, AccountState };

export const MIN_VIEWPORT = 320 as const;

/**
 * The width of the Sign in button at its default label: its 12px padding twice, its border twice
 * and the word. An app with a longer label sets `--account-menu-room` on the control or above it.
 */
const DEFAULT_ROOM = '4.5rem';

export interface AccountMenuLink {
  label: string;
  href: string;
  icon?: React.ReactNode;
}

export interface AccountMenuLabels {
  signIn: string;
  signOut: string;
  signingOut: string;
  signOutFailed: string;
  /** The trigger's accessible name, given the display name. */
  menu: (name: string) => string;
  /** What to call a person with no name and no email. */
  fallbackName: string;
}

export interface AccountMenuLinkRenderProps {
  href: string;
  className?: string;
  /** Put this on the element you return, so the part keeps its `data-slot`. */
  'data-slot'?: string;
  children: React.ReactNode;
}

export interface AccountMenuProps extends Omit<React.ComponentProps<'div'>, 'children'> {
  state: AccountState;
  /** The sign-in page. The current page is added as `?next=` unless `here` is the sign-in page. */
  signInHref: string;
  /** The page the person is on, a path. Used to build `?next=`. Read from your router, not here. */
  here?: string;
  /** Links between the header and Sign out. */
  links?: readonly AccountMenuLink[];
  /** May return a promise. A rejection is shown (a polite message) and passed to `onError`. */
  onSignOut: () => void | Promise<void>;
  onError?: (error: unknown) => void;
  /** The same seam as `Topbar`: a router's Link. Defaults to a plain `<a>`. */
  renderLink?: (props: AccountMenuLinkRenderProps) => React.ReactElement;
  labels?: Partial<AccountMenuLabels>;
}

export const DEFAULT_LABELS: AccountMenuLabels = {
  signIn: 'Sign in',
  signOut: 'Sign out',
  signingOut: 'Signing out…',
  signOutFailed: 'We could not sign you out. Try again.',
  menu: (name) => `Account menu for ${name}`,
  fallbackName: DEFAULT_FALLBACK_NAME,
};

const defaultRenderLink: NonNullable<AccountMenuProps['renderLink']> = ({ href, className, children, ...rest }) => (
  <a href={href} className={className} {...rest}>
    {children}
  </a>
);

const SIGN_IN_CLASS = buttonVariants({ variant: 'outline', size: 'sm' });

function AccountMenu({
  state,
  signInHref,
  here,
  links = [],
  onSignOut,
  onError,
  renderLink = defaultRenderLink,
  labels: labelOverrides,
  className,
  style,
  ...props
}: AccountMenuProps) {
  const labels = { ...DEFAULT_LABELS, ...labelOverrides };
  const [open, setOpen] = React.useState(false);
  const [pending, setPending] = React.useState(false);
  const [failed, setFailed] = React.useState(false);
  const busy = React.useRef(false);
  const trigger = React.useRef<HTMLButtonElement>(null);

  async function signOut() {
    if (busy.current) return;
    busy.current = true;
    setPending(true);
    setFailed(false);
    try {
      await onSignOut();
      setOpen(false);
    } catch (error) {
      setOpen(false);
      setFailed(true);
      onError?.(error);
      trigger.current?.focus();
    } finally {
      busy.current = false;
      setPending(false);
    }
  }

  return (
    <div
      data-slot="account-menu"
      data-state={state.status}
      data-account-id={state.status === 'signed-in' ? state.account.id : undefined}
      data-min-viewport={String(MIN_VIEWPORT)}
      className={cn('flex min-h-control items-center justify-end', className)}
      style={{ minInlineSize: `var(--account-menu-room, ${DEFAULT_ROOM})`, ...style }}
      {...props}
    >
      {state.status === 'unknown' ? (
        <span
          data-slot="account-menu-placeholder"
          aria-hidden="true"
          inert
          className="invisible block h-control-sm min-w-full"
        />
      ) : null}
      {state.status === 'signed-out'
        ? renderLink({
            href: buildSignInHref(signInHref, here),
            className: SIGN_IN_CLASS,
            'data-slot': 'account-menu-sign-in',
            children: labels.signIn,
          })
        : null}
      {state.status === 'signed-in' ? (
        <SignedIn
          account={state.account}
          labels={labels}
          links={links}
          renderLink={renderLink}
          open={open}
          onOpenChange={(next) => {
            setOpen(next);
            if (next) setFailed(false);
          }}
          pending={pending}
          failed={failed}
          onSignOut={signOut}
          triggerRef={trigger}
        />
      ) : null}
    </div>
  );
}
AccountMenu.displayName = 'AccountMenu';

interface SignedInProps {
  account: Account;
  labels: AccountMenuLabels;
  links: readonly AccountMenuLink[];
  renderLink: NonNullable<AccountMenuProps['renderLink']>;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  pending: boolean;
  failed: boolean;
  onSignOut: () => void;
  triggerRef: React.Ref<HTMLButtonElement>;
}

function SignedIn({
  account,
  labels,
  links,
  renderLink,
  open,
  onOpenChange,
  pending,
  failed,
  onSignOut,
  triggerRef,
}: SignedInProps) {
  const name = accountDisplayName(account, labels.fallbackName);
  const email = account.email?.trim();
  return (
    <>
      <DropdownMenu open={open} onOpenChange={onOpenChange}>
        <DropdownMenuTrigger
          ref={triggerRef}
          data-slot="account-menu-trigger"
          aria-label={labels.menu(name)}
          className="relative rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background after:absolute after:-inset-1 after:rounded-full after:content-['']"
        >
          <Avatar className="size-control">
            {account.imageUrl ? <AvatarImage src={account.imageUrl} alt="" referrerPolicy="no-referrer" /> : null}
            <AvatarFallback aria-hidden="true">{accountInitials(account)}</AvatarFallback>
          </Avatar>
        </DropdownMenuTrigger>
        <DropdownMenuContent align="end" className="max-w-[calc(100vw-2rem)] min-w-56">
          <DropdownMenuLabel data-slot="account-menu-header">
            <span dir="auto" title={name} className="block truncate font-medium">
              {name}
            </span>
            {email ? (
              <span dir="auto" title={email} className="block truncate text-xs font-normal text-muted-foreground">
                {email}
              </span>
            ) : null}
          </DropdownMenuLabel>
          <DropdownMenuSeparator />
          {links.map((link) => (
            <MenuLink key={link.href} link={link} renderLink={renderLink} />
          ))}
          <DropdownMenuItem
            data-slot="account-menu-sign-out"
            closeOnClick={false}
            disabled={pending}
            onClick={onSignOut}
          >
            {pending ? labels.signingOut : labels.signOut}
          </DropdownMenuItem>
        </DropdownMenuContent>
      </DropdownMenu>
      <VisuallyHidden role="status" aria-live="polite" data-slot="account-menu-live">
        {failed ? labels.signOutFailed : ''}
      </VisuallyHidden>
    </>
  );
}

function MenuLink({ link, renderLink }: { link: AccountMenuLink; renderLink: NonNullable<AccountMenuProps['renderLink']> }) {
  const content = (
    <>
      {link.icon}
      {link.label}
    </>
  );
  return (
    <DropdownMenuItem data-slot="account-menu-link" render={renderLink({ href: link.href, children: content })}>
      {content}
    </DropdownMenuItem>
  );
}

export { AccountMenu };

export interface Account {
  /** Opaque to the kit. Used as a React key and as `data-account-id`. */
  id: string;
  firstName?: string | null;
  lastName?: string | null;
  email?: string | null;
  imageUrl?: string | null;
}

export type AccountState =
  | { status: 'unknown' }
  | { status: 'signed-out' }
  | { status: 'signed-in'; account: Account };

export type AccountEvent =
  | { type: 'read'; account: Account | null }
  | { type: 'change'; account: Account | null }
  | { type: 'reset' };

export const DEFAULT_FALLBACK_NAME = 'Your account';

/** The fake origin a path is resolved against. `.invalid` never resolves to a real host. */
const FAKE_ORIGIN = 'http://return.invalid';
const MAX_PATH = 2048;

/** A path: `/`, then not `/` or `\`, then no whitespace, no control character, no backslash. */
const SAFE_PATH = /^\/(?![/\\])[^\s\\\x00-\x1f\x7f]*$/;

/**
 * Only a path on this site comes back out; anything else is `fallback` (the app's own
 * constant, never checked). Never throws.
 */
export function safeReturnPath(next: unknown, fallback = '/'): string {
  return typeof next === 'string' &&
    next.length <= MAX_PATH &&
    SAFE_PATH.test(next) &&
    new URL(next, FAKE_ORIGIN).origin === FAKE_ORIGIN
    ? next
    : fallback;
}

const present = (value: string | null | undefined): string => (value ?? '').trim();

/** First name, else the start of the email, else `fallback`. Never an empty string. */
export function accountDisplayName(
  account: Pick<Account, 'firstName' | 'email'> | null,
  fallback: string = DEFAULT_FALLBACK_NAME,
): string {
  const first = present(account?.firstName);
  if (first) return first;
  const email = present(account?.email);
  const at = email.indexOf('@');
  const local = at < 0 ? email : email.slice(0, at);
  return local.trim() || fallback;
}

function graphemes(text: string): string[] {
  if (typeof Intl.Segmenter === 'function') {
    return Array.from(new Intl.Segmenter(undefined, { granularity: 'grapheme' }).segment(text), (s) => s.segment);
  }
  return Array.from(text);
}

const firstGrapheme = (text: string): string => graphemes(text)[0] ?? '';

/**
 * Up to two letters, upper-cased: the first of the first name and the first of the last name; if
 * there is neither, the first of the email; if there is nothing, `?`. Scripts with no case
 * (Hebrew, Arabic, Han) come out unchanged.
 */
export function accountInitials(
  account: Pick<Account, 'firstName' | 'lastName' | 'email'> | null,
): string {
  const names = [firstGrapheme(present(account?.firstName)), firstGrapheme(present(account?.lastName))].join('');
  const letters = names || firstGrapheme(present(account?.email));
  return letters ? letters.toLocaleUpperCase() : '?';
}

/** The path of an address: no query, no fragment, no trailing slash (the root becomes empty). */
const pagePath = (address: string): string => address.split(/[?#]/, 1)[0]!.replace(/\/+$/, '');

/**
 * The sign-in address with a safe `?next=`. `signIn` comes back unchanged when `here` is absent,
 * empty, the sign-in page itself (`/sign-in` and `/sign-in/` are one page) or not a path on this
 * site (it is left out, never encoded). `signIn` may already have a query; it must have no fragment.
 */
export function signInHref(signIn: string, here?: string | null): string {
  if (!here || pagePath(here) === pagePath(signIn)) return signIn;
  const next = safeReturnPath(here, '');
  if (!next) return signIn;
  return `${signIn}${signIn.includes('?') ? '&' : '?'}next=${encodeURIComponent(next)}`;
}

export const UNKNOWN: AccountState = { status: 'unknown' };
const SIGNED_OUT: AccountState = { status: 'signed-out' };

const sameAccount = (a: Account, b: Account): boolean =>
  a.id === b.id &&
  a.firstName === b.firstName &&
  a.lastName === b.lastName &&
  a.email === b.email &&
  a.imageUrl === b.imageUrl;

const settle = (state: AccountState, account: Account | null): AccountState => {
  if (!account) return state.status === 'signed-out' ? state : SIGNED_OUT;
  if (state.status === 'signed-in' && sameAccount(state.account, account)) return state;
  return { status: 'signed-in', account };
};

/**
 * The state under `useAccount`. `read` is the first answer and counts only while nothing is
 * known: a late `read` never overwrites a newer `change`. `change` always counts. An equal
 * account returns the same object, so nothing re-renders. `reset` goes back to `unknown` (the
 * adapter was swapped for another).
 */
export function reduceAccount(state: AccountState, event: AccountEvent): AccountState {
  if (event.type === 'reset') return UNKNOWN;
  if (event.type === 'read' && state.status !== 'unknown') return state;
  return settle(state, event.account);
}

/**
 * @interlace/ui — patterns/account-menu-model
 *
 * The pure half of `AccountMenu`: what to call a person, what to put in an avatar with no photo,
 * the sign-in address that carries the page they were on, the one check that decides whether an
 * address they come back to is on this site, and the reducer under `useAccount`. No DOM, no
 * `window`, no storage, no network: a server, a test and an agent can all use it.
 *
 * ## `safeReturnPath`
 *
 * A "return to" address (`?next=`) is the classic open redirect: the sign-in page sends the
 * person wherever the link says. Only a path on this site may come back out, for any input,
 * including the ones a browser rewrites. A browser deletes tabs and newlines from an address
 * before it reads it, so `/\t/evil.com` is a path to a prefix check and `//evil.com` to the
 * browser. So the rule refuses what a browser would rewrite, and then asks the parser:
 *
 *   1. It is a string, 1 to 2048 characters.
 *   2. It starts with `/`, and the next character is not `/` or `\`.
 *   3. No whitespace (any Unicode space, line separator or paragraph separator), no control
 *      character (C0 and DEL) and no backslash appears anywhere in it.
 *   4. Parsed with `new URL` against a fixed fake origin, it still has that origin.
 *
 * Anything else is the fallback. The function never throws.
 *
 * **An encoded slash is allowed.** `/%2F%2Fevil.com` is a path on this site: a browser does not
 * decode `%2F` before it resolves an address, so it can never become `//`. It is kept as given.
 * Whoever reads the path out of the address and decodes it again owns that second step, and must
 * run `safeReturnPath` on the decoded value too ("use it on the reading side, not only when you
 * build the link").
 *
 * The same rule as the hand-written `safeNext` a first consumer shipped and tested with 22 cases,
 * with one addition: the 2048 limit.
 * Step 4 cannot fail after steps 1 to 3 (it is defence in depth), so a mutation of it is an
 * equivalent mutant.
 *
 * ## Names
 *
 * `accountDisplayName` is what to greet someone by: first name, else the start of the email, else
 * a plain label. `accountInitials` is up to two letters for an avatar with no photo, counted in
 * grapheme clusters (`Intl.Segmenter` where the runtime has it, `Array.from` otherwise, which
 * can still cut a ZWJ emoji sequence in the middle), so an emoji, a letter with a combining mark
 * or a Hebrew or Han name is not cut in half.
 */

'use client';

import * as React from 'react';

/**
 * @interlace/ui — useAccount
 *
 * Turns the app's own sign-in service into the state `AccountMenu` shows: `unknown`, then
 * `signed-out` or `signed-in`. The service is the app's (Supabase, Auth.js, Clerk, a cookie);
 * nothing here names one. The app writes an adapter in about ten lines:
 *
 *   const adapter: AccountAdapter = {
 *     read: async () => toAccount(await service.getSession()),
 *     subscribe: (onChange) => service.onChange((session) => onChange(toAccount(session))),
 *   };
 *
 * `read` is called once on mount (it may return a promise); `subscribe`, when present, reports
 * later changes (a sign-in, a sign-out, a better profile) and returns the unsubscribe. The hook
 * holds the state and nothing else: it never reads or writes a session, a cookie or a storage key.
 *
 * - The first render is `unknown`, on the server and in the browser alike, so the markup matches
 *   and nothing flashes the wrong state.
 * - A `read` that fails is `signed-out`. An app that wants the failure reported wraps its adapter.
 * - Unmounting unsubscribes, and an answer that arrives after it is ignored.
 * - A later `read` never overwrites a newer change (see `reduceAccount`).
 * - Keep the adapter's identity stable (module scope or `useMemo`): a new one means a new
 *   subscription and a fresh `unknown`.
 * - `useAccount(null)` stays `unknown`, for an app whose accounts are switched off.
 */

import { reduceAccount, UNKNOWN, type Account, type AccountState } from '@/components/ui/patterns/account-menu-model';

export interface AccountAdapter {
  /** The current account or null. Called once on mount. */
  read(): Account | null | Promise<Account | null>;
  /** Later changes. Returns the unsubscribe. */
  subscribe?(onChange: (account: Account | null) => void): () => void;
}

export function useAccount(adapter: AccountAdapter | null): AccountState {
  const [state, dispatch] = React.useReducer(reduceAccount, UNKNOWN);

  React.useEffect(() => {
    dispatch({ type: 'reset' });
    if (!adapter) return undefined;
    let live = true;
    const unsubscribe = adapter.subscribe?.((account) => {
      if (live) dispatch({ type: 'change', account });
    });
    new Promise<Account | null>((resolve) => resolve(adapter.read())).then(
      (account) => {
        if (live) dispatch({ type: 'read', account });
      },
      () => {
        if (live) dispatch({ type: 'read', account: null });
      },
    );
    return () => {
      live = false;
      unsubscribe?.();
    };
  }, [adapter]);

  return state;
}
